import java.util.Scanner;

public class CourierService {
    private String cname;
    private double weight;
    private char type;
    private double bill;

    public CourierService() {
        cname = "";
        weight = 0.0;
        type = 'D';
        bill = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Customer Name: ");
        cname = in.nextLine();
        System.out.print("Enter Parcel Weight (in grams): ");
        weight = in.nextDouble();
        System.out.print("Enter Delivery Type ('D' for Domestic, 'I' for International): ");
        type = in.next().toUpperCase().charAt(0);
    }

    public void compute() {
        if (type == 'D') {
            if (weight <= 500) {
                bill = 50.0;
            } else if (weight <= 1000) {
                bill = 50.0 + Math.ceil((weight - 500) / 500.0) * 40.0;
            } else {
                bill = 50.0 + 40.0 + Math.ceil((weight - 1000) / 500.0) * 30.0;
            }
        } else if (type == 'I') {
            double units = Math.ceil(weight / 500.0);
            bill = 250.0 + (units * 120.0);
        } else {
            bill = 0.0;
            System.out.println("Invalid Delivery Type code.");
        }
    }

    public void printDetails() {
        System.out.println("\n============== COURIER INVOICE ==============");
        System.out.println("Customer Name     : " + cname);
        System.out.println("Parcel Weight     : " + weight + " grams");
        System.out.println("Delivery Category : " + (type == 'D' ? "Domestic" : "International"));
        System.out.println("Total Charges     : Rs. " + bill);
        System.out.println("==============================================");
    }

    public static void main(String[] args) {
        CourierService parcel = new CourierService();
        parcel.input();
        parcel.compute();
        parcel.printDetails();
    }
}
```

