import java.util.Scanner;

public class CityBubbleSort {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        String[] cities = new String[N];

        System.out.println("Enter names of " + N + " cities:");
        for (int i = 0; i < N; i++) {
            System.out.print("City [" + (i + 1) + "]: ");
            cities[i] = sc.nextLine().trim();
        }

        System.out.println("\nCities before sorting:");
        for (String c : cities) {
            System.out.print(c + " | ");
        }
        System.out.println();

        // Bubble sort on String array
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N - 1 - i; j++) {
                if (cities[j].compareToIgnoreCase(cities[j + 1]) > 0) {
                    String temp = cities[j];
                    cities[j] = cities[j + 1];
                    cities[j + 1] = temp;
                }
            }
        }

        System.out.println("\nCities in Alphabetical Order (Ascending):");
        for (int i = 0; i < N; i++) {
            System.out.println((i + 1) + ". " + cities[i]);
        }
    }
}
```

