import java.util.Scanner;

public class ParagraphAnalyzer {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter text passage:");
        String text = in.nextLine().trim();

        int sentenceCount = 0;
        int wordCount = 0;
        int vowelCount = 0;
        int letterCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        boolean inWord = false;

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);

            // Sentence termination check
            if (ch == '.' || ch == '?' || ch == '!') {
                sentenceCount++;
            }

            // Word counting logic
            if (Character.isWhitespace(ch)) {
                inWord = false;
            } else {
                if (!inWord) {
                    wordCount++;
                    inWord = true;
                }
            }

            // Character category check
            if (Character.isLetter(ch)) {
                letterCount++;
                char upper = Character.toUpperCase(ch);
                if (upper == 'A' || upper == 'E' || upper == 'I' || upper == 'O' || upper == 'U') {
                    vowelCount++;
                }
            } else if (Character.isDigit(ch)) {
                digitCount++;
            } else if (!Character.isWhitespace(ch)) {
                specialCount++;
            }
        }

        System.out.println("\n=========== PASSAGE ANALYSIS ===========");
        System.out.println("Total Sentences    : " + sentenceCount);
        System.out.println("Total Words        : " + wordCount);
        System.out.println("Total Vowels       : " + vowelCount);
        System.out.println("Alphabetic Letters : " + letterCount);
        System.out.println("Numeric Digits     : " + digitCount);
        System.out.println("Special Characters : " + specialCount);
        System.out.println("=========================================");
    }
}
```

