import java.util.Scanner;

public class TwinPrimeCheck {
    // Helper method to check if a number is prime
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter first positive integer (a): ");
        int a = sc.nextInt();
        System.out.print("Enter second positive integer (b): ");
        int b = sc.nextInt();

        boolean primeA = isPrime(a);
        boolean primeB = isPrime(b);

        System.out.println("\nPrime Status:");
        System.out.println(a + " is " + (primeA ? "PRIME" : "NOT PRIME"));
        System.out.println(b + " is " + (primeB ? "PRIME" : "NOT PRIME"));

        if (primeA && primeB && Math.abs(a - b) == 2) {
            System.out.println("\n(" + a + ", " + b + ") are TWIN PRIMES.");
        } else {
            System.out.println("\n(" + a + ", " + b + ") are NOT Twin Primes.");
        }
    }
}
```

