import java.util.Scanner;

public class NonBoundaryMatrix {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter order of square matrix N (3 to 10): ");
        int n = in.nextInt();

        if (n < 3 || n > 10) {
            System.out.println("Invalid matrix dimension. N must be between 3 and 10.");
            return;
        }

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        System.out.println("\nOriginal Matrix:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.printf("%4d", mat[i][j]);
            }
            System.out.println();
        }

        int interiorSum = 0;
        System.out.println("\nNon-Boundary (Interior) Elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Interior elements are not in first row, last row, first col, or last col
                if (i > 0 && i < n - 1 && j > 0 && j < n - 1) {
                    System.out.printf("%4d", mat[i][j]);
                    interiorSum += mat[i][j];
                } else {
                    System.out.print("    "); // 4 blank spaces for boundary
                }
            }
            System.out.println();
        }

        System.out.println("\nSum of Non-Boundary Elements = " + interiorSum);
    }
}
```

