public class OverloadArea {
    // Area of Circle
    public double area(double r) {
        return Math.PI * r * r;
    }

    // Area of Rectangle
    public double area(double l, double b) {
        return l * b;
    }

    // Area of Triangle (Heron's Formula)
    public double area(double a, double b, double c) {
        double s = (a + b + c) / 2.0;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    public static void main(String[] args) {
        OverloadArea calc = new OverloadArea();

        // Circle: radius = 7.0
        double circleArea = calc.area(7.0);
        System.out.printf("Area of Circle (r = 7.0)         = %.2f sq. units\n", circleArea);

        // Rectangle: length = 12.5, breadth = 8.0
        double rectArea = calc.area(12.5, 8.0);
        System.out.printf("Area of Rectangle (12.5 x 8.0)  = %.2f sq. units\n", rectArea);

        // Triangle: sides = 5.0, 6.0, 7.0
        double triArea = calc.area(5.0, 6.0, 7.0);
        System.out.printf("Area of Triangle (5.0, 6.0, 7.0) = %.2f sq. units\n", triArea);
    }
}
```

